func (this *Test_org_eclipse_swt_browser_Browser) Test_TabTraversalOutOfBrowser() {
	junit.AssumeFalse(SwtTestUtilIsCocoa, "Not currently working on macOS, see https://github.com/eclipse-platform/eclipse.platform.swt/issues/1644")
	junit.AssumeFalse(SwtTestUtilIsGTK, "Not currently working on Linux, see https://github.com/eclipse-platform/eclipse.platform.swt/issues/1644")
	var text *swt.Text = swt.NewText(upcastswtShellToswtComposite(this.shell), swt.NONE)
	this.shell.Open()
	this.browser.ForceFocus()
	var changedFired *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	this.browser.AddLocationListener(browser.LocationListenerChangedAdapter(func(e *browser.LocationEvent) {
		changedFired.Set(true)
	}))
	this.browser.SetText("Hello world")
	junit.AssertTrue(this.WaitForPassCondition(changedFired.Get))
	junit.AssertTrue(this.browser.IsFocusControl())
	junit.AssertFalse(text.IsFocusControl())
	var textGainedFocus *jrt.AtomicBoolean = jrt.NewAtomicBoolean(false)
	text.AddFocusListener(swt.FocusListenerFocusGainedAdapter(func(e *swt.FocusEvent) {
		textGainedFocus.Set(true)
	}))
	this.browser.GetShell().ForceActive()
	var event *swt.Event = swt.NewEvent()
	event.Type = swt.KeyDown
	event.KeyCode = int32(swt.TAB)
	swt.DisplayGetDefault().Post(event)
	junit.AssertTrue(this.WaitForPassCondition(textGainedFocus.Get))
	junit.AssertFalse(this.browser.IsFocusControl())
	junit.AssertTrue(text.IsFocusControl())
}

