func (this *Test_org_eclipse_swt_browser_Browser) Test_evaluate_OpeningNewWindow() {
	{
		var server *EchoHttpServer = NewEchoHttpServer()
		defer server.Close()
		var initialLoad *jrt.AtomicBoolean = jrt.NewAtomicBoolean()
		var openWindowListenerCalled *jrt.AtomicBoolean = jrt.NewAtomicBoolean()
		this.browser.AddProgressListener(browser.ProgressListenerCompletedAdapter(func(e *browser.ProgressEvent) {
			initialLoad.Set(true)
		}))
		this.browser.AddOpenWindowListener(&OpenWindowListenerFunc{fn: func(event *browser.WindowEvent) {
			event.Required = true
			openWindowListenerCalled.Set(true)
		}})
		var html string = jrt.Format("<button id=\"button\" onClick=\"window.open('%s');\">open eclipse.org</button>\n", []any{server.GetEchoUrl("test_evaluate_OpeningNewWindow")})
		this.browser.SetText(html)
		this.WaitForPassCondition(initialLoad.Get)
		this.browser.Evaluate("\tdocument.getElementById(\"button\").click();\n")
		this.WaitForPassCondition(openWindowListenerCalled.Get)
	}
}
